

import { NgModule } from '@angular/core';
import { RouterModule, Routes } from '@angular/router';

import { HomeComponent } from './home/home.component';
import { SearchComponent } from './search/search.component';
import { OwnerBoatWizardComponent } from './owner-boat-wizard/owner-boat-wizard.component';
import {OwnerBenefitsComponent} from './owner-benefits/owner-benefits.component';
import {ContactusComponent} from './contactus/contactus.component';
import {AboutPlatformComponent} from './about-platform/about-platform.component';

const routes: Routes = [
  { path: '', component: HomeComponent },
  { path: 'home', component: HomeComponent },
  { path: 'search', component: SearchComponent },
  { path: 'owner-benefits', component: OwnerBenefitsComponent },
  { path: 'owner-boat-wizard', component: OwnerBoatWizardComponent },
  { path: 'contactus', component: ContactusComponent },
  { path: 'about-platform', component: AboutPlatformComponent },
];

@NgModule({
  imports: [
    RouterModule.forChild(routes)
  ],
  exports: [RouterModule]
})
export class LandingpageRoutingModule { }
