
import { Component, OnInit } from '@angular/core';
import { CommonModule } from '@angular/common';
import { FormArray, FormBuilder, FormGroup, ReactiveFormsModule, Validators } from '@angular/forms';
import { Router, ActivatedRoute, RouterLink } from '@angular/router';
import { StoreDbService } from 'godigital-lib';

type AnyObj = Record<string, any>;

@Component({
    selector: 'app-owner-boat-wizard',
    standalone: true,
    imports: [CommonModule, ReactiveFormsModule, RouterLink],
    templateUrl: './owner-boat-wizard.component.html',
})
export class OwnerBoatWizardComponent implements OnInit {
    step = 0;
    saving = false;
    loading = false;
    error?: string;

    ownerId = '';  // resolved from current user (see notes)
    boatId = '';   // new or existing

    // file buffers (we store File objects until save)
    homeHeroFile?: File;
    boatHeroFile?: File;
    boatGalleryFiles: File[] = [];
    skipperPhotoFile?: File;

    // eventSlug -> files
    eventGalleryFiles: Record<string, File[]> = {};
    form: FormGroup;

    get eventsArr(): FormArray {
        return this.form.get('events') as FormArray;
    }

    constructor(
        private fb: FormBuilder,
        private storeDb: StoreDbService,
        private router: Router,
        private route: ActivatedRoute
    ) {
        this.form = this.fb.group({
            // MAINPAGE
            mainpage: this.fb.group({
                siteName: ['', [Validators.required]],
                heroTitle: ['', [Validators.required]],
                heroLead: [''],
                heroImage: ['home/hero.jpg'], // relative
            }),

            // BOAT
            boat: this.fb.group({
                boatId: [''], // filled on save if new
                boatSlug: ['', [Validators.required]],
                name: ['', [Validators.required]],
                model: [''],
                type: ['catamaran', [Validators.required]], // "type" in your boats :contentReference[oaicite:10]{index=10}
                capacity: [10, [Validators.required, Validators.min(1)]],
                overnightGuests: [0],
                cabins: [0],
                bathrooms: [0],
                length: [0],
                beam: [0],
                draft: [0],
                homePort: [''],
                locationArea: [''],
                shortDescription: [''],
                detailedDescription: [''],
                highlights: this.fb.control<string>(''),
                equipment: this.fb.control<string>(''),
                comfort: this.fb.control<string>(''),
                heroImage: [''], // relative e.g. boat/<slug>/hero.jpg
                gallery: this.fb.control<string>(''), // we’ll set array at save
            }),

            // EVENTS
            events: this.fb.array([]),

            // SKIPPER
            skipper: this.fb.group({
                skipperId: ['main-skipper'],
                name: ['', [Validators.required]],
                role: ['Lead skipper & host'],
                shortBio: [''],
                longBio: [''],
                yearsExperience: [0],
                photo: ['skippers/skipper.jpg'], // relative
                favoriteAreas: this.fb.control<string>(''),
                safetyFocus: this.fb.control<string>(''),
                styleTags: this.fb.control<string>(''),
            })
        });


    }

    async ngOnInit(): Promise<void> {
        this.ownerId = await this.resolveOwnerIdForCurrentUser();

        const boatIdParam = this.route.snapshot.paramMap.get('boatId');
        this.boatId = boatIdParam || '';

        if (this.boatId) {
            this.loading = true;
            try {
                await this.loadExisting(this.boatId);
            } finally {
                this.loading = false;
            }
        } else {
            // start with 1 event by default
            this.addEvent();
        }
    }

    // ---------------------------------------------------------------------------
    // UI actions
    // ---------------------------------------------------------------------------

    next(): void { this.step = Math.min(this.step + 1, 4); }
    back(): void { this.step = Math.max(this.step - 1, 0); }

    addEvent(): void {
        this.eventsArr.push(this.fb.group({
            eventSlug: ['', [Validators.required]],
            title: ['', [Validators.required]],
            subtitle: [''],
            description: [''],
            duration: ['2.5h'],
            location: [''],
            tags: this.fb.control<string>(''),
            heroImage: [''], // relative e.g. events/<slug>/hero.jpg
            gallery: this.fb.control<string>(''), // array set at save
        }));
    }

    removeEvent(i: number): void {
        const slug = (this.eventsArr.at(i)?.value?.eventSlug || '').trim();
        if (slug) delete this.eventGalleryFiles[slug];
        this.eventsArr.removeAt(i);
    }

    onPickHomeHero(ev: Event): void {
        const f = (ev.target as HTMLInputElement).files?.[0];
        if (!f) return;
        this.homeHeroFile = f;
        this.form.get('mainpage.heroImage')?.setValue('home/hero.jpg');
    }

    onPickBoatHero(ev: Event): void {
        const f = (ev.target as HTMLInputElement).files?.[0];
        if (!f) return;
        this.boatHeroFile = f;
        const slug = this.slugify(this.form.get('boat.boatSlug')?.value || '');
        this.form.get('boat.heroImage')?.setValue(`boat/${slug}/${f.name}`);
    }

    onPickBoatGallery(ev: Event): void {
        const files = Array.from((ev.target as HTMLInputElement).files || []);
        if (!files.length) return;
        this.boatGalleryFiles.push(...files);
    }

    onPickSkipperPhoto(ev: Event): void {
        const f = (ev.target as HTMLInputElement).files?.[0];
        if (!f) return;
        this.skipperPhotoFile = f;
        this.form.get('skipper.photo')?.setValue(`skippers/${f.name}`);
    }

    onPickEventGallery(eventSlug: string, ev: Event): void {
        const files = Array.from((ev.target as HTMLInputElement).files || []);
        if (!files.length) return;
        const slug = this.slugify(eventSlug);
        this.eventGalleryFiles[slug] = [...(this.eventGalleryFiles[slug] || []), ...files];
    }

    async saveAll(): Promise<void> {
        this.error = undefined;
        if (this.form.invalid) {
            this.error = 'Please complete required fields.';
            return;
        }

        this.saving = true;
        try {
            // 1) upload files (and build galleries)
            const ownerRoot = `mainpages/${this.ownerId}`;

            // HOME hero
            if (this.homeHeroFile) {
                await this.uploadToStorage(`${ownerRoot}/home/${this.homeHeroFile.name}`, this.homeHeroFile);
                // keep RTDB as "home/xxx"
                this.form.get('mainpage.heroImage')?.setValue(`home/${this.homeHeroFile.name}`);
            }

            // BOAT hero + gallery
            const boatSlug = this.slugify(this.form.get('boat.boatSlug')?.value || '');
            const boatGalleryRel: string[] = [];

            if (this.boatHeroFile) {
                await this.uploadToStorage(`${ownerRoot}/boat/${boatSlug}/${this.boatHeroFile.name}`, this.boatHeroFile);
                this.form.get('boat.heroImage')?.setValue(`boat/${boatSlug}/${this.boatHeroFile.name}`);
            }

            for (const f of this.boatGalleryFiles) {
                await this.uploadToStorage(`${ownerRoot}/boat/${boatSlug}/${f.name}`, f);
                boatGalleryRel.push(`boat/${boatSlug}/${f.name}`);
            }

            // SKIPPER photo
            if (this.skipperPhotoFile) {
                await this.uploadToStorage(`${ownerRoot}/skippers/${this.skipperPhotoFile.name}`, this.skipperPhotoFile);
                this.form.get('skipper.photo')?.setValue(`skippers/${this.skipperPhotoFile.name}`);
            }

            // EVENTS galleries
            const eventsValue = this.eventsArr.value as AnyObj[];
            const eventsPayload: Record<string, AnyObj> = {};

            for (const e of eventsValue) {
                const slug = this.slugify(e.eventSlug || '');
                const files = this.eventGalleryFiles[slug] || [];
                const relGallery: string[] = [];

                for (const f of files) {
                    await this.uploadToStorage(`${ownerRoot}/events/${slug}/${f.name}`, f);
                    relGallery.push(`events/${slug}/${f.name}`);
                }

                // pick first as hero if none
                const hero = e.heroImage || (relGallery.length ? relGallery[0] : '');

                eventsPayload[slug] = {
                    ctaLabel: 'Request a quote',
                    ctaLink: `/tours/${slug}`,
                    description: e.description || '',
                    details: {
                        gallery: relGallery,
                        hero: {
                            badge: 'Boat experience — Côte d’Azur',
                            heroImage: hero,
                            highlights: this.csvToArr(e.tags).slice(0, 4),
                            lead: e.subtitle || '',
                            title: e.title || ''
                        },
                        // keep it minimal now; you can extend to match your full shape later :contentReference[oaicite:11]{index=11}
                    },
                    duration: e.duration || '',
                    eventId: slug,
                    gallery: relGallery,
                    image: hero,
                    location: e.location || '',
                    subtitle: e.subtitle || '',
                    tags: this.csvToArr(e.tags),
                    title: e.title || ''
                };
            }

            // 2) write RTDB nodes

            // Generate boatId if new
            let boatId = (this.form.get('boat.boatId')?.value || '').trim();
            if (!boatId) {
                boatId = String(Date.now()); // replace by your own ID strategy
                this.form.get('boat.boatId')?.setValue(boatId);
            }

            const mp = this.form.get('mainpage')?.value as AnyObj;
            const boat = this.form.get('boat')?.value as AnyObj;
            const skipper = this.form.get('skipper')?.value as AnyObj;

            // backendmainpage/<ownerId>
            await this.putRTDB(`backendmainpage/${this.ownerId}`, {
                ...mp,
                mainpageId: this.ownerId,
                ownerId: this.ownerId
            });

            // backendboats/<ownerId>/<boatId>  (matches your structure :contentReference[oaicite:12]{index=12})
            await this.putRTDB(`backendboats/${this.ownerId}/${boatId}`, {
                ...boat,
                boatId,
                boatSlug,
                ownerId: this.ownerId,
                highlights: this.csvToArr(boat.highlights),
                equipment: this.csvToArr(boat.equipment),
                comfort: this.csvToArr(boat.comfort),
                gallery: boatGalleryRel.length ? boatGalleryRel : (boat.heroImage ? [boat.heroImage] : []),
                image: boat.heroImage || (boatGalleryRel[0] || ''),
                ctaLabel: `View ${boat.name || boat.model || 'boat'}`,
                ctaLink: `/boat/${boatSlug}`
            });

            // backendevents/<ownerId>/events/<eventSlug>  (matches your structure :contentReference[oaicite:13]{index=13})
            await this.putRTDB(`backendevents/${this.ownerId}`, {
                ownerId: this.ownerId,
                signatureTitle: 'Signature Trips',
                signatureSubtitle: `Hand-picked boat experiences curated by ${mp.siteName || 'our host'}`,
                signatureTagline: 'Sunset sails, day escapes, parties and coastline discovery.',
                events: eventsPayload
            });

            // backendskippers/<ownerId>/skippers/<skipperId> (matches your structure :contentReference[oaicite:14]{index=14})
            await this.putRTDB(`backendskippers/${this.ownerId}/skippers/${skipper.skipperId}`, {
                skipperId: skipper.skipperId,
                ownerId: this.ownerId,
                name: skipper.name,
                role: skipper.role,
                shortBio: skipper.shortBio,
                longBio: skipper.longBio,
                yearsExperience: skipper.yearsExperience || 0,
                photo: skipper.photo,
                photos_json: skipper.photo ? [skipper.photo] : [],
                favoriteAreas: this.csvToArr(skipper.favoriteAreas),
                safetyFocus: this.csvToArr(skipper.safetyFocus),
                styleTags: this.csvToArr(skipper.styleTags),
                showOnSite: true,
                sortOrder: 1
            });

            // backendowners/<ownerId> minimal sync (summary skipper block exists in your data :contentReference[oaicite:15]{index=15})
            await this.patchRTDB(`backendowners/${this.ownerId}`, {
                ownerId: this.ownerId,
                displayName: mp.siteName,
                skipper: {
                    name: skipper.name,
                    role: skipper.role,
                    shortBio: skipper.shortBio,
                    photo: skipper.photo,
                    photos_json: skipper.photo ? [skipper.photo] : []
                },
                state: 'active'
            });

            // done
            this.router.navigate(['/owner/boats']);
        } catch (e: any) {
            console.error(e);
            this.error = e?.message || 'Save failed.';
        } finally {
            this.saving = false;
        }
    }

    // ---------------------------------------------------------------------------
    // LOAD EXISTING (optional)
    // ---------------------------------------------------------------------------
    private async loadExisting(boatId: string): Promise<void> {
        // boat
        const boat = await this.storeDb.getObject<AnyObj>(`backendboats/${this.ownerId}/${boatId}`, null as any);
        if (boat) this.form.get('boat')?.patchValue(boat);

        // mainpage
        const mp = await this.storeDb.getObject<AnyObj>(`backendmainpage/${this.ownerId}`, null as any);
        if (mp) this.form.get('mainpage')?.patchValue(mp);

        // events (load and build array)
        const evRoot = await this.storeDb.getObject<AnyObj>(`backendevents/${this.ownerId}`, null as any);
        const events = evRoot?.events || {};
        this.eventsArr.clear();
        Object.keys(events).forEach(slug => {
            const ev = events[slug];
            this.eventsArr.push(this.fb.group({
                eventSlug: [slug, Validators.required],
                title: [ev?.title || '', Validators.required],
                subtitle: [ev?.subtitle || ''],
                description: [ev?.description || ''],
                duration: [ev?.duration || ''],
                location: [ev?.location || ''],
                tags: [Array.isArray(ev?.tags) ? ev.tags.join(', ') : ''],
                heroImage: [ev?.image || ''],
                gallery: [''],
            }));
        });

        // skipper (load main-skipper if exists)
        const sk = await this.storeDb.getObject<AnyObj>(`backendskippers/${this.ownerId}/skippers/main-skipper`, null as any);
        if (sk) {
            this.form.get('skipper')?.patchValue({
                ...sk,
                favoriteAreas: Array.isArray(sk.favoriteAreas) ? sk.favoriteAreas.join(', ') : '',
                safetyFocus: Array.isArray(sk.safetyFocus) ? sk.safetyFocus.join(', ') : '',
                styleTags: Array.isArray(sk.styleTags) ? sk.styleTags.join(', ') : '',
            });
        }
    }

    // ---------------------------------------------------------------------------
    // RTDB helpers
    // NOTE: adapt these calls to your StoreDbService write API.
    // ---------------------------------------------------------------------------
    private async putRTDB(path: string, value: Record<string, any>): Promise<void> {
        // Your updateObject() uses .set() under the hood, so it’s a PUT.
        await this.storeDb.updateObject(path, value, null as any);
    }

    private async patchRTDB(path: string, patch: Record<string, any>): Promise<void> {
        // Partial update (merge)
        await this.storeDb.partialUpdateObject(path, patch, null as any);
    }

    private async uploadToStorage(fullPath: string, file: File): Promise<void> {
        // fullPath example: "mainpages/<ownerId>/boat/<slug>/my.jpg"
        // StoreDbService.uploadFile wants (directory, file)
        const cleaned = fullPath.replace(/^\/+/, '');
        const parts = cleaned.split('/');
        const filename = parts.pop()!;
        const directory = parts.join('/');

        // Ensure uploaded file keeps desired filename (optional)
        // If you want to force the filename, you’d need a Blob rename strategy.
        // For now, we just upload with file.name and rely on fullPath using file.name.
        if (file.name !== filename) {
            // If names differ, you can either:
            // - ignore and accept file.name (recommended simplest)
            // - or create a new File with the desired name (browser support OK)
            file = new File([file], filename, { type: file.type });
        }

        await this.storeDb.uploadFile(directory, file);
    }

    private csvToArr(v: any): string[] {
        const s = (v || '').toString().trim();
        if (!s) return [];
        return s.split(',').map(x => x.trim()).filter(Boolean);
    }

    private slugify(v: any): string {
        return (v || '')
            .toString()
            .trim()
            .toLowerCase()
            .replace(/['"]/g, '')
            .replace(/[^a-z0-9]+/g, '-')
            .replace(/-+/g, '-')
            .replace(/^-|-$/g, '');
    }

    private async resolveOwnerIdForCurrentUser(): Promise<string> {
        // Replace by: take uid from Firebase auth, then match backendowners.primaryUserId/userIds :contentReference[oaicite:16]{index=16}
        return 'owner-home-tagine-volant';
    }
}
