import {
  Component,
  ChangeDetectionStrategy,
  ChangeDetectorRef,
  OnDestroy,
  OnInit,
} from '@angular/core';
import { Router, ActivatedRoute } from '@angular/router';
import { BehaviorSubject, combineLatest, Subscription } from 'rxjs';
import { debounceTime, distinctUntilChanged, map } from 'rxjs/operators';
import { StoreDbService, OBJECTNAME } from 'godigital-lib';

interface BoatDoc {
  boatId: string;           // can be numeric/string unique id in RTDB
  ownerId?: string;

  name?: string;
  model?: string;
  type?: string;            // catamaran | sailing | motor | ...
  homePort?: string;        // e.g. Antibes
  locationArea?: string;    // e.g. "Cannes • Antibes • Lérins Islands"

  shortDescription?: string;
  detailedDescription?: string;

  gallery?: string[];
  image?: string;
  heroImage?: string;
}

interface MainpageDoc {
  mainpageId: string; // owner-home-layali
  siteName?: string;
  heroTitle?: string;
}

interface EventDoc {
  eventId?: string;
  title?: string;
  // anything else in your RTDB
}

interface BoatSearchCard {
  mainpageId: string;     // owner-home-layali
  slug: string;           // layali
  boatId: string;         // RTDB boatId or key
  title: string;          // boat name/model or siteName
  type?: string;
  homePort?: string;
  locationArea?: string;

  supportedEventIds: string[];
  supportedEventTitles: string[];

  posterUrl?: string;
}

type FilterState = {
  q: string;
  area: string;          // free-text or dropdown
  boatType: string;      // dropdown
  eventIds: string[];    // multi-select
};

@Component({
  selector: 'app-search',
  templateUrl: './search.component.html',
  styleUrls: ['./search.component.css'],
  changeDetection: ChangeDetectionStrategy.OnPush,
})
export class SearchComponent implements OnInit, OnDestroy {
  loading = false;
  error?: string;

  private subs = new Subscription();
  private readonly storageRootFolder = 'mainpages';

  /** Loaded catalog */
  private cards$ = new BehaviorSubject<BoatSearchCard[]>([]);

  /** Filters */
  private filter$ = new BehaviorSubject<FilterState>({
    q: '',
    area: '',
    boatType: '',
    eventIds: [],
  });

  /** Derived filter options (from data) */
  options$ = this.cards$.pipe(
    map(cards => {
      const areas = new Set<string>();
      const types = new Set<string>();
      const events = new Map<string, string>(); // id -> title

      for (const c of cards) {
        // areas from homePort + tokens in locationArea
        if (c.homePort) areas.add(c.homePort);
        const tokens = (c.locationArea || '')
          .split('•')
          .map(s => s.trim())
          .filter(Boolean);
        tokens.forEach(t => areas.add(t));

        if (c.type) types.add(c.type);

        c.supportedEventIds.forEach((id, i) => {
          const t = c.supportedEventTitles[i] || id;
          if (!events.has(id)) events.set(id, t);
        });
      }

      return {
        areas: Array.from(areas).sort((a, b) => a.localeCompare(b)),
        types: Array.from(types).sort((a, b) => a.localeCompare(b)),
        events: Array.from(events.entries())
          .map(([id, title]) => ({ id, title }))
          .sort((a, b) => a.title.localeCompare(b.title)),
      };
    })
  );

  /** ViewModel */
  vm$ = combineLatest([
    this.cards$,
    this.filter$.pipe(debounceTime(120), distinctUntilChanged((a, b) => JSON.stringify(a) === JSON.stringify(b))),
  ]).pipe(
    map(([cards, f]) => {
      const q = (f.q || '').trim().toLowerCase();
      const area = (f.area || '').trim().toLowerCase();
      const boatType = (f.boatType || '').trim().toLowerCase();
      const selectedEvents = (f.eventIds || []).filter(Boolean);

      const filtered = cards.filter(c => {
        // text query matches title, port, area, type
        if (q) {
          const hay = [
            c.title,
            c.slug,
            c.type,
            c.homePort,
            c.locationArea,
            ...c.supportedEventTitles,
          ]
            .filter(Boolean)
            .join(' ')
            .toLowerCase();

          if (!hay.includes(q)) return false;
        }

        // boat type filter
        if (boatType) {
          if ((c.type || '').toLowerCase() !== boatType) return false;
        }

        // area filter: matches homePort OR locationArea contains token
        if (area) {
          const hp = (c.homePort || '').toLowerCase();
          const la = (c.locationArea || '').toLowerCase();
          if (!hp.includes(area) && !la.includes(area)) return false;
        }

        // event filter: all selected events must be supported
        if (selectedEvents.length) {
          const set = new Set(c.supportedEventIds);
          for (const evId of selectedEvents) {
            if (!set.has(evId)) return false;
          }
        }

        return true;
      });

      filtered.sort((a, b) => a.title.localeCompare(b.title));

      return {
        filters: f,
        total: cards.length,
        shown: filtered.length,
        cards: filtered,
      };
    })
  );

  constructor(
    private storeDb: StoreDbService,
    private router: Router,
    private route: ActivatedRoute,
    private cdr: ChangeDetectorRef
  ) { }

  ngOnInit(): void {
    // 1) Apply initial filters from /search?...
    this.subs.add(
      this.route.queryParamMap.subscribe(params => {
        const location = params.get('location') || '';
        const boatType = params.get('boatType') || '';
        const eventType = params.get('eventType') || '';
        const q = params.get('q') || ''; // optional

        // map homepage eventType -> RTDB eventIds
        const eventIds = eventType ? [this.mapHomepageEventTypeToEventId(eventType)] : [];
        const cleanedEventIds = eventIds.filter(Boolean) as string[];

        this.filter$.next({
          q,
          area: location,          // your filter uses "area"
          boatType,
          eventIds: cleanedEventIds
        });

        this.cdr.markForCheck();
      })
    );

    // 2) Load catalog
    void this.loadBoatCatalog();
  }

  ngOnDestroy(): void {
    this.subs.unsubscribe();
  }

  // ---------------------------------------------------------------------------
  // FILTER HANDLERS
  // ---------------------------------------------------------------------------

  setQuery(v: string): void {
    const cur = this.filter$.value;
    this.filter$.next({ ...cur, q: v || '' });
  }

  setArea(v: string): void {
    const cur = this.filter$.value;
    this.filter$.next({ ...cur, area: v || '' });
  }

  setBoatType(v: string): void {
    const cur = this.filter$.value;
    this.filter$.next({ ...cur, boatType: v || '' });
  }

  toggleEvent(eventId: string, checked: boolean): void {
    const cur = this.filter$.value;
    const set = new Set(cur.eventIds || []);
    if (checked) set.add(eventId);
    else set.delete(eventId);
    this.filter$.next({ ...cur, eventIds: Array.from(set) });
  }

  clearFilters(): void {
    this.filter$.next({ q: '', area: '', boatType: '', eventIds: [] });
  }

  // ---------------------------------------------------------------------------
  // NAVIGATION
  // ---------------------------------------------------------------------------

  openBoat(card: BoatSearchCard): void {
    // safest: pass full mainpageId
    this.router.navigate(['/mainpage'], { queryParams: { mainpage: card.mainpageId } });
  }

  // ---------------------------------------------------------------------------
  // LOADING / BUILD CATALOG
  // ---------------------------------------------------------------------------

  private async loadBoatCatalog(): Promise<void> {
    this.loading = true;
    this.error = undefined;
    this.cdr.markForCheck();

    try {
      // New RTDB structure (Jan 2026):
      //  - backendowners/mainpage
      //  - backendowners/boats/{boatId}/boat
      //  - backendowners/events/{boatId}/{eventId}
      const mpDoc = (await this.storeDb.getObject<any>('backendowners/mainpage', null as any)) as MainpageDoc | null;
      const mainpageId = (mpDoc as any)?.ownerId || (mpDoc as any)?.mainpageId || 'owner-home-layali';
      const slug = this.slugFromMainpageId(mainpageId);

      const boatsNode: any = await this.storeDb.getObject<any>('backendowners/boats', null as any);
      const boatsById = this.nodeToMap<any>(boatsNode);

      const eventsRoot: any = await this.storeDb.getObject<any>('backendowners/events', null as any);
      const eventsByBoatId = this.nodeToMap<any>(eventsRoot);

      const cards: BoatSearchCard[] = [];

      for (const boatId of Object.keys(boatsById)) {
        const wrapper = boatsById[boatId];
        const src = wrapper?.boat || wrapper;
        if (!src || typeof src !== 'object') continue;

        const evMap = this.nodeToMap<EventDoc>(eventsByBoatId?.[boatId] || {});
        const supportedEventIds = Object.keys(evMap);
        const supportedEventTitles = supportedEventIds.map(id => evMap[id]?.title || id);

        const title = src.name || src.model || (mpDoc as any)?.siteName || (mpDoc as any)?.heroTitle || slug || mainpageId;

        // In the adapted export, these are already full URLs.
        let posterUrl: string | undefined = src.mainImage || src.heroImage || src.image;
        posterUrl =
          (await this.resolvePathToDownloadUrl(mainpageId, posterUrl)) ||
          (await this.resolvePathToDownloadUrl(mainpageId, src.image)) ||
          posterUrl;

        cards.push({
          mainpageId,
          slug,
          boatId: String(src.boatId || boatId),
          title,
          type: src.type,
          homePort: src.homePort,
          locationArea: src.locationArea,
          supportedEventIds,
          supportedEventTitles,
          posterUrl,
        });
      }

      this.cards$.next(cards.filter(x => !!x.mainpageId && !!x.boatId));
    } catch (e: any) {
      console.error('[search] load error', e);
      this.error = e?.message || 'Failed to load boats catalog.';
      this.cards$.next([]);
    } finally {
      this.loading = false;
      this.cdr.markForCheck();
    }
  }

  // ---------------------------------------------------------------------------
  // HELPERS
  // ---------------------------------------------------------------------------
  private mapHomepageEventTypeToEventId(v: string): string | null {
    const x = (v || '').trim().toLowerCase();
    if (!x) return null;

    // ✅ IMPORTANT: these MUST match your RTDB eventId keys in backendevents
    const map: Record<string, string> = {
      sunset: 'sunset',
      afterwork: 'afterwork',
      business: 'business-meeting', // adjust if your RTDB key differs
      'day-escape': 'day-escape',   // adjust if your RTDB key differs
      'evjf-evg': 'evjf',           // adjust if your RTDB key differs
    };

    return map[x] || x; // fallback: assume already an eventId
  }

  private nodeToMap<T>(node: any): Record<string, T> {
    if (!node || typeof node !== 'object') return {};
    return node as Record<string, T>;
  }

  private slugFromMainpageId(mainpageId: string): string {
    const s = (mainpageId || '').trim().toLowerCase();
    if (!s) return '';
    return s.startsWith('owner-home-') ? s.substring('owner-home-'.length) : s;
  }

  private async resolvePathToDownloadUrl(mainpageId: string, path?: string | null): Promise<string | undefined> {
    if (!path) return undefined;
    const p = String(path).trim();
    if (!p) return undefined;

    if (/^https?:\/\//i.test(p)) return p;

    const clean = p.replace(/^\/+/, '');

    // New bucket structure
    if (clean.startsWith('boatowners/')) {
      return this.safeGetDownloadUrl(clean);
    }

    if (clean.startsWith(`${this.storageRootFolder}/`)) {
      return this.safeGetDownloadUrl(clean);
    }

    if (/^owner-home-[^/]+\//i.test(clean)) {
      return this.safeGetDownloadUrl(`${this.storageRootFolder}/${clean}`);
    }

    // relative to mainpage folder (bucket structure)
    return this.safeGetDownloadUrl(`${this.storageRootFolder}/${mainpageId}/${clean}`);
  }

  private async safeGetDownloadUrl(fullStoragePath: string): Promise<string | undefined> {
    try {
      return await this.storeDb.getDownloadUrl(fullStoragePath);
    } catch {
      return undefined;
    }
  }

  // nice display
  eventChips(card: BoatSearchCard): string {
    return (card.supportedEventTitles || []).slice(0, 3).join(' • ');
  }
}
