import { Component, OnInit } from '@angular/core';
import { CommonModule } from '@angular/common';
import { Router, RouterLink } from '@angular/router';
import { FormsModule } from '@angular/forms';

import { StoreDbService } from 'godigital-lib';

interface HomepageTestimonial {
  title: string;
  text: string;
  author: string;
  origin: string;
}

interface MainpageDoc {
  mainpageId: string;     // owner-home-layali
  ownerId?: string;
  siteName?: string;
  heroTitle?: string;
  heroLead?: string;
  heroImage?: string;     // home/hero.jpg (relative) or full url
  aboutBoatTitle?: string;
  defaultLocation?: string;
  signatureTitle?: string;
}

interface BoatCard {
  mainpageId: string;
  slug: string;
  displayName: string;  // what user searches by (siteName / aboutBoatTitle / heroTitle)
  location?: string;
  posterUrl?: string;   // resolved to tokened url
}

@Component({
  selector: 'app-home',
  standalone: true,
  imports: [CommonModule, RouterLink, FormsModule],
  templateUrl: './home.component.html'
})
export class HomeComponent implements OnInit {

  heroImageUrl: string = 'assets/img/home/home-hero-generic.jpg';

  // SECTION 1: Find my experience -> just navigates to /search
  // (no form here)

  // SECTION 2: Find my boat (type boat name)
  boatQuery = '';
  loadingBoats = true;
  boatsError?: string;

  boatsAll: BoatCard[] = [];
  boatsShown: BoatCard[] = [];

  // SECTION 4: Feedbacks
  testimonials: HomepageTestimonial[] = [
    {
      title: 'Perfect sunset',
      text: 'We booked last minute and had the most beautiful golden-hour cruise with a super friendly owner.',
      author: 'Camille',
      origin: 'Paris'
    },
    {
      title: 'Great EVJF at sea',
      text: 'Easy to book, clear communication with the boat owner and an amazing afternoon for the bride-to-be.',
      author: 'Sarah',
      origin: 'Lyon'
    },
    {
      title: 'Business afterwork done right',
      text: 'Our team was blown away by the setting. Smooth booking and great coordination.',
      author: 'Thomas',
      origin: 'Marseille'
    }
  ];

  // FAQ items
  faqs = [
    {
      q: 'Do I pay Boatify or the boat owner?',
      a: 'Boatify helps you discover boats and send booking requests. The transaction (payment + agreement) is made directly with the boat owner.'
    },
    {
      q: 'Can I book a skipper and extra services?',
      a: 'Yes. Each boat/experience can offer extras like skipper, drinks, seabob, catering, etc. You select them during the booking request.'
    },
    {
      q: 'How do I find the right boat for my event?',
      a: 'Use “Find my experience” to filter by area, date, guests, boat type, and event type. Then compare the boats and owners.'
    },
    {
      q: 'I’m a boat owner — how do I list my boat?',
      a: 'Click “Host my boats” and follow the onboarding. You’ll create your mainpage, add boat details, events, photos, and availability.'
    }
  ];

  private readonly storageRootFolder = 'mainpages';

  constructor(
    private storeDb: StoreDbService,
    private router: Router
  ) {}

  async ngOnInit(): Promise<void> {
    await this.loadBoatsCatalog();
  }

  // ---------------------------------------------------------------------------
  // SECTION 1
  // ---------------------------------------------------------------------------
  goFindExperience(): void {
    this.router.navigate(['/search']);
  }

  // ---------------------------------------------------------------------------
  // SECTION 2
  // ---------------------------------------------------------------------------
  setBoatQuery(v: string): void {
    this.boatQuery = v || '';
    this.applyBoatFilter();
  }

  openBoat(card: BoatCard): void {
    // go to “private pages” hub (your mainpage component)
    this.router.navigate(['/mainpage'], { queryParams: { mainpage: card.mainpageId } });
  }

  private async loadBoatsCatalog(): Promise<void> {
    this.loadingBoats = true;
    this.boatsError = undefined;

    try {
      const node: any = await this.storeDb.getObject<any>('backendmainpage', -1);

      if (!node || typeof node !== 'object') {
        this.boatsAll = [];
        this.applyBoatFilter();
        return;
      }

      const docs: MainpageDoc[] = Object.keys(node).map(key => {
        const row = node[key] || {};
        if (!row.mainpageId) row.mainpageId = key;
        return row as MainpageDoc;
      });

      const cards = await Promise.all(docs.map(d => this.toBoatCard(d)));

      // Keep only valid ones + sort
      this.boatsAll = cards
        .filter(c => !!c.mainpageId && !!c.displayName)
        .sort((a, b) => a.displayName.localeCompare(b.displayName));

      this.applyBoatFilter();
    } catch (e: any) {
      console.error(e);
      this.boatsError = e?.message || 'Unable to load boats list.';
      this.boatsAll = [];
      this.applyBoatFilter();
    } finally {
      this.loadingBoats = false;
    }
  }

  private applyBoatFilter(): void {
    const q = (this.boatQuery || '').trim().toLowerCase();

    const filtered = !q
      ? [...this.boatsAll]
      : this.boatsAll.filter(b =>
          (b.displayName || '').toLowerCase().includes(q) ||
          (b.slug || '').toLowerCase().includes(q)
        );

    // show a limited number on homepage for UX
    this.boatsShown = filtered.slice(0, 9);
  }

  private async toBoatCard(doc: MainpageDoc): Promise<BoatCard> {
    const mainpageId = doc.mainpageId || '';
    const slug = this.slugFromMainpageId(mainpageId);

    const displayName =
      doc.siteName ||
      doc.aboutBoatTitle ||
      doc.heroTitle ||
      slug ||
      mainpageId;

    const location =
      doc.defaultLocation ||
      this.extractLocationFromLead(doc.heroLead || '');

    // poster:
    // 1) use doc.heroImage if present
    // 2) else fallback to first file in mainpages/<id>/boat
    let posterUrl = await this.resolvePathToDownloadUrl(mainpageId, doc.heroImage);

    if (!posterUrl) {
      const boatRoot = `${this.storageRootFolder}/${mainpageId}/boat`;
      const flat = await this.storeDb.listImageUrlsFlat(boatRoot);
      posterUrl = flat?.length ? flat[0] : undefined;
    }

    return { mainpageId, slug, displayName, location, posterUrl };
  }

  private slugFromMainpageId(mainpageId: string): string {
    const lower = (mainpageId || '').trim().toLowerCase();
    return lower.startsWith('owner-home-') ? lower.substring('owner-home-'.length) : lower;
  }

  private extractLocationFromLead(lead: string): string | undefined {
    if (!lead) return undefined;
    const places = ['Nice', 'Antibes', 'Cannes', 'Monaco', 'Lérins', 'Villefranche'];
    const found = places.filter(p => lead.toLowerCase().includes(p.toLowerCase()));
    return found.length ? found.join(' • ') : undefined;
  }

  private async resolvePathToDownloadUrl(mainpageId: string, path?: string | null): Promise<string | undefined> {
    if (!path) return undefined;
    const p = (path || '').trim();
    if (!p) return undefined;

    if (/^https?:\/\//i.test(p)) return p;

    let clean = p.replace(/^\/+/, '');

    if (clean.startsWith(`${this.storageRootFolder}/`)) {
      return this.safeGetDownloadUrl(clean);
    }

    if (/^owner-home-[^/]+\//i.test(clean)) {
      return this.safeGetDownloadUrl(`${this.storageRootFolder}/${clean}`);
    }

    return this.safeGetDownloadUrl(`${this.storageRootFolder}/${mainpageId}/${clean}`);
  }

  private async safeGetDownloadUrl(fullStoragePath: string): Promise<string | undefined> {
    try {
      return await this.storeDb.getDownloadUrl(fullStoragePath);
    } catch {
      return undefined;
    }
  }

  // ---------------------------------------------------------------------------
  // SECTION 3
  // ---------------------------------------------------------------------------
  goHostMyBoats(): void {
    this.router.navigate(['/owner-boat-wizard']);
  }
}
