import { Component, ChangeDetectionStrategy } from '@angular/core';
import { CommonModule } from '@angular/common';
import { Router, RouterLink } from '@angular/router';

@Component({
  selector: 'app-owner-benefits',
  standalone: true,
  imports: [CommonModule, RouterLink],
  templateUrl: './owner-benefits.component.html',
  changeDetection: ChangeDetectionStrategy.OnPush
})
export class OwnerBenefitsComponent {
  /** Change this if your onboarding route is different */
  readonly OWNER_ONBOARDING_ROUTE = '/owner-boat-wizard';

  /** Optional: if you want to show an example URL pattern */
  readonly exampleUrl = 'https://boatify.fr/owner-home-layali';

  /** Subscription disclaimer (keep it simple, adjust wording later) */
  readonly subscriptionNote =
    'Boatify is subscription-based to cover infrastructure costs. No commission on your bookings.';

  constructor(private router: Router) {}

  goCreateEnvironment(): void {
    this.router.navigate([this.OWNER_ONBOARDING_ROUTE]);
  }
}
